CREATE POLICY "Flyers are readable" ON storage.objects FOR SELECT TO anon, authenticated USING (bucket_id = 'flyers');
CREATE POLICY "Users upload own flyers" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'flyers' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "Users update own flyers" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'flyers' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "Users delete own flyers" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'flyers' AND (storage.foldername(name))[1] = auth.uid()::text);